INSERT INTO `resource_archive` VALUES (1,1,1,NULL,'resource_title_list_news','tag','nash','list-news',NULL,NULL,'[]','','{\"html.php\":\"<div class=\\\"news-list\\\">\\n  <h2><?= translate(\'news_title\') ?></h2>\\n  \\n  <div for=\\\"news_entry of this.news\\\">\\n    <h3>{news_entry.title}</h3>\\n    <p><innerhtml value=\\\"{news_entry.text}\\\"></innerhtml></p>\\n    <p><?= translate(\'published_on\') ?> {news_entry.publish_date}</p>\\n  </div>\\n\\n</div>\",\"javascript\":\"class NewsList extends Tag {\\n  init() {\\n    this.loadNews()\\n  }\\n  \\n  loadNews() {\\n    resource.action(\'load_news\').then(result => {\\n      this.setAttribute(\'news\', result)\\n    })\\n  }\\n}\",\"load_news.php\":\"<?php\\n  $news = $db->getAll(\'news\');\\n  echo json_encode($news);\\n?>\"}','[{\"name\":\"innerhtml\",\"type\":\"tag\",\"version\":\"1.1.0\"}]','1.0.0','000010000000000',NULL,NULL,NULL,NULL,'10ca57964541b11cc80a1fa4c3552ae5','published','2024-06-02 08:27:40','test',3600),(13,1,1,NULL,'property_detail','tag','RealEstate','property-detail',NULL,'[{\"name\":\"id\",\"title\":\"property_id\",\"type\":\"number\",\"required\":true,\"options\":[],\"title_translated\":\"Property ID\",\"documentation_translated\":\"\"}]',NULL,'property_detail_documentation','{\"html.php\":\"<div class=\\\"property-detail\\\" if=\\\"!!this.property\\\">\\n  <h2>{this.property.address}</h2>\\n  <p>{this.property.city}, {this.property.state} {this.property.zip_code}</p>\\n  \\n  <div class=\\\"property-images\\\">\\n    <img src=\\\"/uploads/properties/{this.property.images}\\\" alt=\\\"Property Image\\\">\\n  </div>\\n  \\n  <div class=\\\"property-info\\\">\\n    <p><strong><?= translate(\'price\') ?>:</strong> ${this.property.price}</p>\\n    <p><strong><?= translate(\'bedrooms\') ?>:</strong> {this.property.bedrooms}</p>\\n    <p><strong><?= translate(\'bathrooms\') ?>:</strong> {this.property.bathrooms}</p>\\n    <p><strong><?= translate(\'square_footage\') ?>:</strong> {this.property.square_footage} sq ft</p>\\n    <p><strong><?= translate(\'property_type\') ?>:</strong> {this.property.property_type}</p>\\n    <p><strong><?= translate(\'year_built\') ?>:</strong> {this.property.year_built}</p>\\n    <p><strong><?= translate(\'lot_size\') ?>:</strong> {this.property.lot_size} acres</p>\\n  </div>\\n  \\n  <div class=\\\"property-description\\\">\\n    <h3><?= translate(\'description\') ?></h3>\\n    <p>{this.property.description}</p>\\n  </div>\\n  \\n  <div class=\\\"property-features\\\">\\n    <h3><?= translate(\'features\') ?></h3>\\n    <ul for=\\\"feature of this.features\\\">\\n      <li>{feature}</li>\\n    </ul>\\n  </div>\\n  \\n  <div class=\\\"property-contact\\\">\\n    <h3><?= translate(\'contact_agent\') ?></h3>\\n    <p>{this.property.agent_name}</p>\\n    <p>{this.property.agent_phone}</p>\\n    <p>{this.property.agent_email}</p>\\n  </div>\\n</div>\",\"javascript\":\"class PropertyDetail extends Tag {\\n    init() {\\n        const propertyId = router$.params.tab;\\n        resource.action(\'get_property_details\', { id: propertyId }).then(result => {\\n            this.setAttribute(\'property\', result);\\n        })\\n    }\\n}\",\"get_property_details.php\":\"<?php\\n  $propertyId = $data[\'id\'];\\n  \\n  $property = $db->get(\'property_listing\', [\'id\' => $propertyId]);\\n  \\n  if (!$property) {\\n    notFound();\\n  }\\n  \\n  //$property[\'images\'] = explode(\',\', $property[\'images\']);\\n  \\n  // Placeholder data for additional fields\\n  $property[\'property_type\'] = \'Single Family\';\\n  $property[\'year_built\'] = 2005;\\n  $property[\'lot_size\'] = 0.5;\\n  $property[\'features\'] = [\'Hardwood Floors\', \'Granite Countertops\', \'Stainless Steel Appliances\'];\\n  $property[\'agent_name\'] = \'John Doe\';\\n  $property[\'agent_phone\'] = \'(123) 456-7890\';\\n  $property[\'agent_email\'] = \'john@example.com\';\\n  \\n  echo json_encode($property);\\n?>\",\"css\":\".property-detail {\\n  max-width: 800px;\\n  margin: 0 auto;\\n  padding: 20px;\\n}\\n\\n.property-images {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\\n  grid-gap: 10px;\\n  margin-bottom: 20px;\\n}\\n\\n.property-images img {\\n  width: 100%;\\n  height: auto;\\n  object-fit: cover;\\n  border-radius: 4px;\\n}\\n\\n.property-info {\\n  margin-bottom: 20px;\\n  display: grid;\\n  grid-template-columns: 1fr 1fr 1fr;\\n  column-gap: 20px;\\n}\\n\\n.property-info  p {\\n    margin-top: 0px;\\n}\\n\\n.property-description {\\n  margin-bottom: 20px;\\n}\\n\\n.property-features ul {\\n  list-style-type: disc;\\n  margin-left: 20px;\\n}\\n\\n.property-contact {\\n  background-color: #f5f5f5;\\n  padding: 20px;\\n  border-radius: 4px;\\n}\"}','[]','1.0.0','000010000000000',NULL,NULL,NULL,NULL,'260a5217eb496cbe71da271bb9f70792','published','2024-06-02 13:58:28','Ai Generator',3600),(14,NULL,1,NULL,'resource_title_task_list','tag','nash','task-list',NULL,NULL,NULL,NULL,'{\"html.php\":\"\\n<div class=\\\"task-list\\\">\\n  <h2>Tasks</h2>\\n  <table>\\n    <thead>\\n      <tr>\\n        <th>Title</th>\\n        <th>Priority</th>\\n        <th>Actions</th>\\n      </tr>\\n    </thead>\\n    <tbody for=\\\"task of this.tasks\\\">\\n      \\n      <tr>\\n        <td>{task.title}</td>\\n        <td><span class=\\\"priority-{task.priority}\\\">{task.priority}</span></td>\\n        <td>\\n          <form.button label=\\\"View\\\" icon=\\\"visibility\\\" (click)=\\\"this.viewTask(task.id)\\\"></form.button>\\n        </td>\\n      </tr>\\n      \\n    </tbody>\\n  </table>\\n</div>\",\"javascript\":\"class TaskList extends Tag {\\n  init() {\\n    this.loadTasks();\\n  }\\n  \\n  loadTasks() {\\n    resource.action(\'get_tasks\').then(result => {\\n      this.setAttribute(\'tasks\', result);\\n    });\\n  }\\n  \\n  viewTask(id) {\\n    router$.goto(\'/task-detail/\' + id);\\n  }\\n}\",\"css\":\".task-list {\\n  padding: 24px;\\n}\\n\\n.task-list h2 {\\n  font-size: 28px;\\n  margin-bot