action(\'load_document\', { id: this.documentId });\\n        this.items = await resource.action(\'load_items\', { document_id: this.documentId });\\n        this.company = await resource.action(\'load_company\');\\n        this.calculateTotals();\\n        this.update();\\n    }\\n\\n    calculateTotals() {\\n        this.subtotal = 0;\\n        this.totalTax = 0;\\n        this.total = 0;\\n\\n        this.items.forEach(item => {\\n            const itemSubtotal = item.quantity * item.unit_price;\\n            const itemTax = itemSubtotal * (item.tax_rate \\/ 100);\\n            \\n            this.subtotal += itemSubtotal;\\n            this.totalTax += itemTax;\\n        });\\n\\n        this.total = this.subtotal + this.totalTax;\\n    }\\n\\n    async printDocument() {\\n        await resource.action(\'print_document\', {\\n            document_id: this.documentId,\\n            items: this.items,\\n            totals: {\\n                subtotal: this.subtotal,\\n                tax: this.totalTax,\\n                total: this.total\\n            }\\n        });\\n    }\\n}\"},\"html\":{\"content\":\"<div class=\\\"sales-document-view\\\">\\n    <div class=\\\"document-header\\\">\\n        <h1>{this.document.title}<\\/h1>\\n        <div class=\\\"status-badge {this.document.status}\\\">\\n            <t>sales_document_status_{this.document.status}<\\/t>\\n        <\\/div>\\n    <\\/div>\\n\\n    <div class=\\\"document-details\\\">\\n        <div class=\\\"detail-row\\\">\\n            <label><t>sales_document_date<\\/t>:<\\/label>\\n            <span>{this.document.date}<\\/span>\\n        <\\/div>\\n        <div class=\\\"detail-row\\\">\\n            <label><t>sales_document_due_date<\\/t>:<\\/label>\\n            <span>{this.document.due_date}<\\/span>\\n        <\\/div>\\n    <\\/div>\\n\\n    <table class=\\\"items-table\\\">\\n        <thead>\\n            <tr>\\n                <th><t>sales_document_item_position<\\/t><\\/th>\\n                <th>