\\n?>\"},\"load_company.php\":{\"content\":\"<?php\\n    $company = $db->get(\'company_settings\', []);\\n    echo json_encode($company);\\n?>\"},\"print_document.php\":{\"content\":\"<?php\\n    $document_id = $data[\'document_id\'];\\n    $items = $data[\'items\'];\\n    $totals = $data[\'totals\'];\\n    \\n    $printTemplate = new PrintTemplateBill();\\n    $document = $db->getById(\'sales_document\', $document_id);\\n    $contact = $db->getById(\'contact\', $document[\'contact_id\']);\\n    $company = $db->get(\'company_settings\', []);\\n    \\n    $result = $printTemplate->generatePDF([\\n        \'document\' => $document,\\n        \'items\' => $items,\\n        \'totals\' => $totals,\\n        \'contact\' => $contact,\\n        \'company\' => $company\\n    ]);\\n    \\n    echo json_encode([\'status\' => \'success\', \'pdf_url\' => $result[\'url\']]);\\n?>\"}}',NULL,'1.1.7967',NULL,NULL,NULL,NULL,NULL,NULL,'private','2024-10-26 19:46:44','AI Generator',NULL),(45,77,1,NULL,'resource_title_create_partner','tag','support','create-partner',NULL,'[{\"name\":\"redirect_url\",\"type\":\"string\",\"required\":true,\"options\":{\"maxlength\":256},\"title\":\"create_partner_redirect_url\"}]',NULL,NULL,'{\"javascript\":\"class CreatePartner extends Tag {\\n    init() {\\n        this.title = \'create_partner_title\';\\n        this.formData = {};\\n    }\\n    \\n    async create(data) {\\n        try {\\n            const result = await resource.action(\'create\', data);\\n            Notification.success(\'partner_created_success\');\\n            Navigation.goto(this.redirect_url || \'\\/admin-partners\');\\n        } catch(error) {\\n            Notification.error(\'partner_creation_failed\');\\n        }\\n    }\\n}\",\"html\":\"<div>\\n    <h1><t>create_partner_title<\\/t><\\/h1>\\n    <form.resource\\n        (submit)=\\\"this.create(event)\\\"\\n        submitlabel=\\\"create_partner_submit\\\"\\n        value=\\\"{this.formData}\\\"\\n        resourcetype=\\