INSERT INTO `step_type_template` VALUES (1,'step_type_template_mail_title','SELECT receiver_contact_id as contact_id, id as message_id FROM mail_message WHERE receiver_contact_id=:contact_id AND mail_template_name LIKE :mail_template_name','form_select_mail_template','/mail-reader/{message_id}','mail_sent'),(2,'step_type_template_query_title','{sql_query}','form_sql_query','{link}','sql_query'),(3,'step_type_template_sales_document_title','SELECT sd.contact_id \r\nFROM sales_document sd \r\nLEFT JOIN sales_document_status sds ON sd.status = sds.name\r\nWHERE sd.contact_id = :contact_id \r\n  AND sd.document_type = :document_type \r\n  AND sds.sequence_no >= (\r\n    SELECT sds2.sequence_no \r\n    FROM sales_document_status sds2 \r\n    WHERE sds2.name = :status\r\n  )','form_sales_document',NULL,'sales_document'),(4,'step_type_template_contact_activity_title','SELECT ca.* \r\nFROM contact_activity ca\r\nJOIN activity_type at ON ca.activity_type_id = at.id\r\nWHERE ca.contact_id = :contact_id\r\nAND at.name = :contact_activity','form_contact_activity_type',NULL,'contact_activity'),(5,'step_type_template_newly_added_title','SELECT * FROM contact WHERE id=:contact_id',NULL,NULL,'newly_added'),(6,'step_type_template_bulk_mailing_title','SELECT contact_id FROM bulk_mailing_receiver WHERE contact_id=:contact_id AND sent=:sent','form_bulk_mailing',NULL,'bulk_mailing'),(9,'step_type_template_deal_lost_title','SELECT c.id FROM contact c LEFT JOIN contact_type ct ON c.contact_type_id = ct.id WHERE ct.name=\'deal_lost\' AND c.id=:contact_id',NULL,NULL,'deal_lost'),(10,'step_type_template_event_invitation_title','SELECT * FROM event_invitation ei LEFT JOIN event e ON e.id = ei.event_id WHERE ei.contact_id=:contact_id AND e.name=:event','form_select_event','/list-events','event_invitation'),(11,'step_type_template_event_registration_title','SELECT * FROM event_participant ep LEFT JOIN event e ON e.id = ep.event_id WHERE ep.contact_id=:contact_id AND e.name=:event','form_select_event','/event-participants/{event_id}','event_registration'),(12,'step_type_template_event_attended_title','SELECT * FROM event_participant ep LEFT JOIN event e ON e.id = ep.event_id WHERE ep.contact_id=:contact_id AND e.name=:event AND ep.attended=1','form_select_event','/event-detail/{event_id}','event_attended'),(13,'step_type_template_meeting_booked_title','SELECT * FROM meeting_participant mp LEFT JOIN meeting m ON mp.meeting_id=m.id LEFT JOIN meeting_type mt ON mt.id = m.meeting_type_id WHERE mt.name = :meeting_type AND contact_id=:contact_id','form_select_meeting_type',NULL,'meeting_booked'),(14,'step_type_template_meeting_confirmed_title','SELECT * FROM meeting_participant mp LEFT JOIN meeting m ON mp.meeting_id=m.id LEFT JOIN meeting_type mt ON  mt.id = m.meeting_type_id WHERE mt.name = :meeting_type AND mp.contact_id=:contact_id AND mp.confirmed=1','form_select_meeting_type',NULL,'meeting_confirmed'),(15,'step_type_template_meeting_attended_title','SELECT * FROM meeting_participant mp LEFT JOIN meeting m ON mp.meeting_id=m.id LEFT JOIN meeting_type mt ON  mt.id = m.meeting_type_id WHERE mt.name = :meeting_type AND mp.contact_id=:contact_id AND mp.attended=1','form_select_meeting_type',NULL,'meeting_attended'),(16,'step_type_template_documents_confirmed_title','SELECT * FROM documents_confirmed WHERE contact_id=:contact_id',NULL,'/manage-documents/{customer_id}','documents_confirmed'),(17,'step_type_template_closed_deal_title','SELECT * FROM closed_deal WHERE customer_contact_id=:contact_id AND booked=1',NULL,NULL,'closed_deal'),(18,'step_type_template_signed_contract_title','SELECT * FROM contract c LEFT JOIN contract_template ct ON ct.id = c.contract_template_id WHERE c.contact_id=:contact_id AND ct.name=:contract_template','form_contract_template',NULL,'signed_contract'),(19,'step_type_tracking_link_clicked_title','SELECT tc.* FROM tracking_click tc LEFT JOIN tracking_link tl ON tl.id = tc.tracking_link_id WHERE tc.contact_id=:contact_id AND tl.name = :tracking_link','form_tracking_link',NULL,'tracking_link_clicked');
/*!40000 ALTER TABLE `step_type_template` ENABLE KEYS */;
