INSERT INTO `translation` VALUES (19711,'message_welcome_mail_alternative','fr','<div style=\"font-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: #222; padding: 20px; margin: 0;max-width: 800px; margin: 0 auto; background: #ffffff; border-radius: 20px; box-shadow: 0 20px 40px rgba(0,0,0,0.1); overflow: hidden;\">\n \n <!-- Header Section -->\n <div style=\"background: linear-gradient(45deg, #e6294d, #7929e6, #2f29e6, #29BAE7); padding: 40px 30px; text-align: center; color: white;\">\n <div style=\"font-size: 80px; margin-bottom: 20px;\">🚀</div>\n <h1 style=\"font-size: 48px; margin: 0; text-shadow: 2px 2px 4px rgba(0,0,0,0.3); font-weight: bold;\">\n<span style=\"color: #FF6B6B;\">Bonjour {firstname}</span>!\n <span style=\"color: #FFE66D;\">BIENVENUE</span> <span style=\"color: #FF6B6B;\">!</span>\n </h1>\n <div style=\"font-size: 60px; margin: 20px 0;\">🪄✨🧙‍♀️🌟</div>\n </div>\n\n <!-- Main Content -->\n <div style=\"padding: 40px 30px;\">\n  \n <!-- Thank You Section -->\n <div style=\"text-align: center; margin-bottom: 40px; background: linear-gradient(135deg, #667eea, #764ba2); color: white; padding: 30px; border-radius: 15px; box-shadow: 0 10px 20px rgba(0,0,0,0.1);\">\n <h2 style=\"font-size: 36px; margin: 0 0 20px 0; text-transform: uppercase; letter-spacing: 2px;\">\n <span style=\"font-size: 50px;\">🤝</span><br>\n <strong>Merci de vous être connecté avec moi sur LinkedIn !</strong>\n </h2>\n </div>\n\n <!-- Introduction Section -->\n <div style=\"background: linear-gradient(135deg, #FF9A9E, #FECFEF); padding: 30px; border-radius: 15px; margin-bottom: 30px; box-shadow: 0 8px 16px rgba(0,0,0,0.1);\">\n <div style=\"text-align: center;\">\n <p style=\"font-size: 24px; color: #34495E; line-height: 1.6; margin: 0;\">\n  <strong style=\"color: #8E44AD;\">JE SUIS LE PDG DE METAYOTA</strong><br>\n  <span style=\"color: #E67E22; font-size: 28px; font-weight: bold;\">🌍 L\'ENTREPRISE INFORMATIQUE LA MOINS CHÈRE DU MONDE ! 🌍</span>\n </p>\n <div style=\"background: #3498DB; color: white; padding: 20px; border-radius: 10px; margin-top: 20px;\">\n  <p style=\"font-size: 22px; margin: 0; font-weight: bold;\">\n   <span style=\"font-size: 40px;\">⚡</span><br>\n      8 ANS DE RECHERCHE ET DÉVELOPPEMENT NOUS AIDENT À CRÉER DES APPLICATIONS D\'ENTREPRISE PARFAITES<br>\n   <span style=\"color: #F1C40F; font-size: 26px;\">EN QUELQUES HEURES AU LIEU DE PLUSIEURS ANNÉES !</span>\n  </p>\n </div>\n </div>\n </div>\n\n <!-- Follow Company Page -->\n <div style=\"background: #0077B5; color: white; padding: 25px; border-radius: 15px; margin-bottom: 30px; text-align: center;\">\n <div style=\"font-size: 50px; margin-bottom: 15px;\">📢</div>\n <h3 style=\"font-size: 28px; margin: 0 0 15px 0;\">SUIVEZ NOTRE PAGE D\'ENTREPRISE SUR LINKEDIN !</h3>\n <a href=\"https://www.linkedin.com/company/metayota/\" style=\"color: #F1C40F; font-size: 20px; font-weight: bold; text-decoration: none; background: rgba(255,255,255,0.2); padding: 10px 20px; border-radius: 25px; display: inline-block;\">\n    🔗 linkedin.com/entreprise/metayota/\n </a>\n </div>\n\n <!-- CRM Section -->\n <div style=\"background: linear-gradient(135deg, #A8E6CF, #88D8C0); padding: 30px; border-radius: 15px; margin-bottom: 30px;\">\n <div style=\"text-align: center;\">\n <div style=\"font-size: 60px; margin-bottom: 20px;\">🤖💼</div>\n <h3 style=\"font-size: 28px; color: #2C3E50; margin: 0 0 20px 0;\">\n     NOUS PROPOSONS ÉGALEMENT <span style=\"color: #E74C3C;\">DES SYSTÈMES CRM ENTIÈREMENT PERSONNALISÉS</span> <span style=\"color: #E74C3C;\">!</span>\n </h3>\n <p style=\"font-size: 20px; color: #34495E; line-height: 1.6;\">\n  <strong>NOTRE TECHNOLOGIE ALIMENTE NOTRE SOCIÉTÉ SŒUR SYGETA CORP. !</strong><br><br>\n  <span style=\"color: #8E44AD; font-weight: bold;\">TOUTES LES TÂCHES DE COMMUNICATION CLIENT PEUVENT ÊTRE AUTOMATISÉES :</span>\n </p>\n    \n <div style=\"display: grid; grid-template-columns: repeat(2, 1fr); gap: 15px; margin: 20px 0; text-align: left;\">\n  <div style=\"background: white; padding: 15px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);\">\n   <span style=\"font-size: 30px;\">✉️</span> <strong>Rédaction de lettres</strong>\n  </div>\n  <div style=\"background: white; padding: 15px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);\">\n     <strong>📋 Offres</strong>\n  </div>\n  <div style=\"background: white; padding: 15px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);\">\n     <strong>💰 Factures</strong>\n  </div>\n  <div style=\"background: white; padding: 15px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);\">\n      📧 <strong>Automatisation des e-mails</strong>\n  </div>\n </div>\n\n <div style=\"background: #3498DB; color: white; padding: 20px; border-radius: 10px; margin-top: 20px;\">\n  <p style=\"font-size: 20px; margin: 0; line-height: 1.6;\">\n   <strong>NOUS METTONS EN PLACE VOTRE PIPELINE DE VENTE - VOUS N\'AVEZ QU\'À APPUYER SUR QUELQUES TOUCHES :</strong><br>\n      📄 Documents créés - 📧 E-mails envoyés - 📝 Formulaires envoyés aux clients\n  </p>\n </div>\n\n <div style=\"margin: 20px 0;\">\n  <a href=\"https://www.sygeta.com/\" style=\"color: #E74C3C; font-size: 22px; font-weight: bold; text-decoration: none; background: white; padding: 15px 30px; border-radius: 25px; display: inline-block; box-shadow: 0 4px 8px rgba(0,0,0,0.2);\">\n      🌐 VISITEZ SYGETA.COM\n  </a>\n </div>\n </div>\n </div>\n\n <!-- Main Website -->\n <div style=\"background: linear-gradient(135deg, #667eea, #764ba2); color: white; padding: 40px; border-radius: 15px; margin-bottom: 30px; text-align: center;\">\n <div style=\"font-size: 80px; margin-bottom: 20px;\">🏢</div>\n <h3 style=\"font-size: 32px; margin: 0 0 20px 0;\">VISITEZ NOTRE SITE WEB PRINCIPAL !</h3>\n <a href=\"https://www.metayota.com/\" style=\"color: #F1C40F; font-size: 28px; font-weight: bold; text-decoration: none; background: rgba(255,255,2